fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    // Input is assumed non-empty by the problem statement, but the code works for any length.
    let n = x.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n {
        // Safe: i < n ensures in-bounds access.
        result.push(x[i]);
        i += 1;
    }

    // Ensures result has exactly the same length as input.
    debug_assert_eq!(result.len(), n);
    result
}